{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/patterns/media-frame.json
    A picture in a fixed ratio that follows the theme. `src` is the picture of the light theme, `darkSrc` the one of the dark theme (without it the dark theme shows `src`). Without both it shows the built-in neutral placeholders (base64 data URIs, one light and one dark), so a page can be laid out before it has pictures; the placeholder stands in for a real `src` and is switched by the theme token. `ratio` comes from the recipe; the corners are the plain theme radius.
    Props (p): alt, src, darkSrc, ratio, className. -#}
{%- set k_PLACEHOLDER = {'light': 'data:image/svg+xml;base64,', 'dark': 'data:image/svg+xml;base64,'} -%}
{%- set v_alt = og_def(p['alt'], none) -%}
{%- set v_src = og_def(p['src'], none) -%}
{%- set v_darkSrc = og_def(p['darkSrc'], none) -%}
{%- set v_ratio = og_def(p['ratio'], '16/9') -%}
{%- set v_lightSrc = og_coalesce([v_src, og_at(k_PLACEHOLDER, 'light')]) -%}
{%- set v_nightSrc = og_coalesce([v_darkSrc, v_src, og_at(k_PLACEHOLDER, 'dark')]) -%}
{%- set c_1 -%}
  {{ og_include('compose/image.html.j2', {'p': {'Src': og_url(og_s(v_lightSrc), true), 'Alt': og_s(v_alt), 'Class': 'absolute inset-0 size-full object-cover dark:hidden', 'Attrs': og_attrs(['data-theme-src', 'light'])}}) }}
  {{ og_include('compose/image.html.j2', {'p': {'Src': og_url(og_s(v_nightSrc), true), 'Alt': og_s(v_alt), 'Class': 'absolute inset-0 hidden size-full object-cover dark:block', 'Attrs': og_attrs(['data-theme-src', 'dark'])}}) }}
{%- endset -%}
{{ og_include('compose/box.html.j2', {'p': {'Class': og_s(og_cnv([og_recipe('blocks/recipes/media-frame.variants.json', {'ratio': v_ratio}), og_def(p['className'], '')])), 'Attrs': og_attrs(['data-slot', 'media-frame', 'data-placeholder', ('false' if og_t(v_src) else 'true')])}, 'children': c_1}) }}
